function Team() {
    return (
        <div className="container">



            <div className="row p-5 mt-5  " style={{ lineHeight: "1.5" }}>
                <div className="col-6 p-5">


                </div>
                <div className="col-6 p-5">
                    <h2>People</h2>
                    <p style={{ fontSize: "18px" }}>
                        <p>Nithin bootstrapped and founded Zerodha in 2010 to overcome the hurdles he faced during his decade long stint as a trader. Today, Zerodha has changed the landscape of the Indian broking industry.
                        </p> <br></br>

                        <p> <a href=" " style={{ textDecoration: "none" }}> Rainmatter</a>, our fintech fund and incubator, has invested in several fintech startups with the goal of growing the Indian capital markets.</p> <br></br>

                        <p>And yet, we are always up to something new every day. Catch up on the latest updates on our blog or see what the media is saying about us or learn more about our business and product philosophies.</p>
                    </p>
                </div>
            </div>

        </div >
    );
}

export default Team;
